 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bars = []
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v == 2]
        if len(cols) >= 2 and cols == list(range(cols[0], cols[-1] + 1)):
            bars.append((r, cols[0], cols[-1]))
    for i, (r0, c0, c1) in enumerate(bars):
        for r1, d0, d1 in bars[i + 1:]:
            if (d0, d1) != (c0, c1):
                continue
            mid = (r0 + r1) // 2
            if mid in (r0, r1) or any(grid[r][c] != 0 for r in range(r0 + 1, r1) for c in range(w) if c not in range(c0, c1 + 1)):
                continue
            # Connector row is the middle of the vertically aligned bars.
            out[mid] = [3] * w
            return out
    return out
